// Builds the email from FiberDoc's summary (see integrations/n8n/README.md for the payload).
const p = $input.first().json.body;
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const c = p.counts || {};
const doc = p.document || {};
const failed = doc.status === 'error';
const prefix = p.test ? '[TEST] ' : '';
const subject = failed
  ? `${prefix}FiberDoc: processing failed for ${doc.name}`
  : `${prefix}FiberDoc: ${doc.name} checked, ${c.failed || 0} failed, ${(c.total || 0) - (c.passed || 0)} open`;
const rows = (p.open_findings || []).map((f) =>
  `<tr><td>${esc(f.rule_id)}</td><td>${esc(f.title)}</td><td>${esc(f.status).replace('_', ' ')}</td><td>${esc(f.severity)}</td><td>${esc(f.explanation)}</td></tr>`).join('');
const html = `
<p>${esc(p.summary)}</p>
<p><b>Project:</b> ${esc(p.project?.name)}<br><b>Document type:</b> ${esc((doc.doc_type || '').replace('_', ' '))}<br><b>Pages:</b> ${esc(doc.page_count)}</p>
<p><b>Failed:</b> ${c.failed || 0} &nbsp; <b>Missing evidence:</b> ${c.missing_evidence || 0} &nbsp; <b>Needs review:</b> ${c.needs_review || 0} &nbsp; <b>Passed:</b> ${c.passed || 0}</p>
${rows ? `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;font-size:13px"><tr><th>Rule</th><th>Finding</th><th>Status</th><th>Severity</th><th>Explanation</th></tr>${rows}</table>` : '<p>No open issues.</p>'}
<p><a href="${esc(p.links?.app)}">Open FiberDoc AI</a> to review. Findings must be confirmed by a human reviewer; nothing is approved automatically.</p>
<p style="color:#888;font-size:12px">Demo rule catalogue: invented example requirements, not official standards.</p>`;
return [{ json: { to: p.recipient, subject, html } }];
